const r = await tools.exec_command({cmd:"python - <<'PY'
import csv,re,math,statistics
from datetime import datetime,timezone


def amount(s):
    s=s.strip()
    if not s: return math.nan
    neg=('CR' in s.upper() or (s.startswith('(') and s.endswith(')')) or '-' in s)
    s=re.sub(r'C[12]', '', s, flags=re.I)
    s=re.sub(r'[A-Za-z\s]', '', s)
    s=''.join(c for c in s if c.isdigit() or c in ',.')
    if not s or not any(c.isdigit() for c in s): return math.nan
    commas=[i for i,c in enumerate(s) if c==',']
    dots=[i for i,c in enumerate(s) if c=='.']
    dec=None
    if commas and dots:
        dec=',' if commas[-1]>dots[-1] else '.'
    elif commas:
        if len(s)-commas[-1]-1 == 2: dec=','
    elif dots:
        if len(s)-dots[-1]-1 == 2: dec='.'
    if dec:
        pos=s.rfind(dec)
        val=''.join(c for c in s[:pos] if c.isdigit())+'.'+''.join(c for c in s[pos+1:] if c.isdigit())
    else:
        val=''.join(c for c in s if c.isdigit())
    try: x=float(val)
    except ValueError: return math.nan
    return -x if neg else x

def parse_time(s):
    if not s: return None
    return datetime.fromisoformat(s.replace('Z','+00:00'))

def parse_notes(s):
    mi=re.search(r'items=(\d+)',s)
    ma=re.search(r'adj=([+-]?(?:\d+(?:\.\d*)?|\.\d+))%',s)
    mf=re.search(r'fee=([+-]?(?:\d+(?:\.\d*)?|\.\d+))',s)
    return (int(mi.group(1)) if mi else None, float(ma.group(1))/100 if ma else 0, float(mf.group(1)) if mf else 0, bool(re.search(r'waive=true',s,re.I)))

with open('dataset/data.csv',newline='',encoding='utf-8-sig') as f: rows=list(csv.DictReader(f))
for i,r in enumerate(rows):
    r['_i']=i;r['_dt']=parse_time(r['event_time']);r['_base']=amount(r['amount_str'])
    r['_items'],adj,fee,waive=parse_notes(r['notes'])
    r['_net']=math.nan if math.isnan(r['_base']) else (0.0 if waive else r['_base']*(1+adj)+fee)
# largest time, real net, earlier order. None is earlier than every real time.
def choicekey(r):
    return (r['_dt'] is not None, r['_dt'] or datetime.min.replace(tzinfo=timezone.utc), not math.isnan(r['_net']), -r['_i'])
best={}
for r in rows:
    rid=r['record_id']
    if rid not in best or choicekey(r)>choicekey(best[rid]): best[rid]=r
lo=datetime(2025,10,1,tzinfo=timezone.utc); hi=datetime(2025,12,31,23,59,59,tzinfo=timezone.utc)
keep=[r for r in best.values() if r['_dt'] is not None and lo<=r['_dt']<=hi and r['channel'].lower()!='phone' and math.isfinite(r['_net'])]
from collections import defaultdict
groups=defaultdict(list)
for r in keep: groups[(r['region'],r['_dt'].strftime('%Y-%m'))].append(r['_net'])
for r in keep:
    vals=groups[(r['region'],r['_dt'].strftime('%Y-%m'))]
    med=statistics.median(vals); mad=statistics.median([abs(x-med) for x in vals])
    r['_med']=med;r['_mad']=mad;r['_z']=0 if mad==0 else .6745*(r['_net']-med)/mad
    eff=max(r['_items'] if r['_items'] is not None else 1,1)
    r['_score']=abs(r['_z'])*math.log1p(eff)
keep.sort(key=lambda r:(-r['_score'],-abs(r['_z']),-r['_dt'].timestamp(),r['record_id']))
print('dedup',len(best),'eligible',len(keep),'groups',len(groups))
print('rank id time region channel amount base notes net n med mad z score')
for j,r in enumerate(keep[:20],1):
    print(j,r['record_id'],r['event_time'],r['region'],repr(r['channel']),repr(r['amount_str']),r['_base'],repr(r['notes']),round(r['_net'],6),r['_items'],round(r['_med'],6),round(r['_mad'],6),round(r['_z'],6),round(r['_score'],6))
print('ANSWER', [r['record_id'] for r in keep[:10]])
PY",workdir:"/app",yield_time_ms:10000,max_output_tokens:10000});
