import csv,re,collections,math
with open('dataset/data.csv',newline='') as f: rows=list(csv.DictReader(f))
for name,pat in [('items',r'items=([^;]*)'),('adj',r'adj=([^;]*)'),('fee',r'fee=([^;]*)'),('waive',r'waive=([^;]*)')]:
    vals=collections.Counter(m.group(1).strip() for r in rows if (m:=re.search(pat,r['notes'],re.I)))
    print(name,'count',sum(vals.values()),'unique',len(vals),'values',vals.most_common(30))
# duplicates of same latest timestamp and how tie was resolved
from datetime import datetime,timezone
from collections import defaultdict
by=defaultdict(list)
for i,r in enumerate(rows):
    if r['event_time']: by[r['record_id']].append((r['event_time'],i,r['amount_str'],r['notes']))
ties=[]
for rid,v in by.items():
    latest=max(x[0] for x in v); vv=[x for x in v if x[0]==latest]
    if len(vv)>1: ties.append((rid,latest,vv))
print('latest timestamp ties',len(ties))
for x in ties[:20]: print(x)
